      { const c = KNOT; kp.push(tube((() => { const pts = []; for (let i = 0; i <= 40; i++) { const t = i / 40, ph = t * TAU * 2.2; pts.push([c[0] + 0.009 * Math.cos(ph) * (1 - 0.3 * t), c[1] + 0.007 * Math.sin(ph), c[2] - 0.003 - 0.004 * t]); } return pts; })(), 0.0028, 8)); }
      const wS = (x, y, z) => W.wBody(x, y, z);
