      for (const ph0 of [0, PI * 0.9]) { const S = []; for (let i = 0; i <= NC; i++) { const ph = ph0 + i * 0.95, p = ringPts[i], c = [0, p[1], H.HCX.z], out = norm([p[0] - c[0], 0, p[2] - c[2]]);
        S.push([p[0] + out[0] * 0.0012 * Math.cos(ph), p[1] + 0.0012 * Math.sin(ph), p[2] + out[2] * 0.0012 * Math.cos(ph)]); } vine.push(tube(S, 0.0014, 6)); }
