        const root3 = [s * cfg.root[0], cfg.root[1], KNOT[2] - 0.004];
        const Dout = [s * Math.cos(cfg.sweep), 0, -Math.sin(cfg.sweep)], UP = [0, 1, 0];
        const rot = cfg.lift - picAng, cr = Math.cos(rot), sr = Math.sin(rot);
